create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_id uuid not null references public.plans(id),amount_toman integer not null check(amount_toman>=0),zarinpal_ref_id text,status text not null default 'pending' check(status in('pending','success','failed','refunded')),created_at timestamptz not null default now());create index if not exists idx_pay_u on public.payments(user_id);create index if not exists idx_pay_s on public.payments(status);
